const X0 = 0.6, Y0 = 0.2;
const hf = (x, y) => 2.4 - 0.22 * x * x - 0.10 * y * y;
const Z0 = hf(X0, Y0);
const tpf = (x, y) => Z0 - 0.264 * (x - X0) - 0.04 * (y - Y0);
