const domeGeo = new THREE.PlaneGeometry(7, 6, 80, 70);
{
  const p = domeGeo.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i);
    p.setXYZ(i, x, hf(x, y), y);
  }
  p.needsUpdate = true;
  domeGeo.computeVertexNormals();
  const n = domeGeo.attributes.normal;
  const L = new THREE.Vector3(-0.45, 0.85, -0.4).normalize();
  const cLo = new THREE.Color(0xE8734A), cHi = new THREE.Color(0xF7C6A0);
