  const tmp = new THREE.Color(), nv = new THREE.Vector3();
  for (let i = 0; i < p.count; i++) {
    const t = THREE.MathUtils.clamp((p.getY(i) + 1.5) / 4.0, 0, 1);
    tmp.copy(cLo).lerp(cHi, t);
    nv.set(n.getX(i), n.getY(i), n.getZ(i));
    const lam = 0.80 + 0.26 * Math.max(0, nv.dot(L));
    tmp.multiplyScalar(lam);
    cols.push(tmp.r, tmp.g, tmp.b);
