const domeMat = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.FrontSide });
const dome = new THREE.Mesh(domeGeo, domeMat);
dome.renderOrder = 0;
scene.add(dome);

// darker under-side so the curled-down skirts read
const backGeo = domeGeo.clone();
{
  const c = backGeo.attributes.color;
  for (let i = 0; i < c.count; i++) c.setXYZ(i, c.getX(i) * 0.80, c.getY(i) * 0.78, c.getZ(i) * 0.78);
  c.needsUpdate = true;
}
const domeBack = new THREE.Mesh(backGeo, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide }));
domeBack.renderOrder = 0;
scene.add(domeBack);

// rim outline along the cut edges of the surface
{
  const pts = [];
  const N = 60;
  for (let i = 0; i <= N; i++) { const x = -3.5 + 7 * i / N; pts.push(W(x, -3, hf(x, -3))); }
  for (let i = 0; i <= N; i++) { const y = -3 + 6 * i / N; pts.push(W(3.5, y, hf(3.5, y))); }
  for (let i = 0; i <= N; i++) { const x = 3.5 - 7 * i / N; pts.push(W(x, 3, hf(x, 3))); }
  for (let i = 0; i <= N; i++) { const y = 3 - 6 * i / N; pts.push(W(-3.5, y, hf(-3.5, y))); }
