const planeBorderMat = new THREE.LineBasicMaterial({ color: 0xC8D5DC, transparent: true, opacity: 0.9 });
const planeBorder = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints([
    W(-3.8, -3.4, tpf(-3.8, -3.4)), W(3.8, -3.4, tpf(3.8, -3.4)),
    W(3.8, 3.4, tpf(3.8, 3.4)), W(-3.8, 3.4, tpf(-3.8, 3.4))
  ]),
  planeBorderMat
);
planeBorder.renderOrder = 3;
scene.add(planeBorder);

/* ── curves & tangent lines ──────────────────────────────────────────────── */
function makeTube(points, color, radius) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, Math.max(32, points.length * 2), radius, 10, false);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, depthWrite: true });
  const m = new THREE.Mesh(geo, mat);
  m.renderOrder = 4;
  scene.add(m);
  return m;
}

// teal curve C1 : section y = 0.2
const c1pts = [];
for (let i = 0; i <= 90; i++) { const x = -3.5 + 7 * i / 90; c1pts.push(W(x, Y0, hf(x, Y0) + 0.02)); }
