// dark red curve C2 : section x = 0.6
const c2pts = [];
for (let i = 0; i <= 90; i++) { const y = -3 + 6 * i / 90; c2pts.push(W(X0, y, hf(X0, y) + 0.02)); }
const curveC2 = makeTube(c2pts, 0xB9322B, 0.036);

function tangentSegment(dirSurf, color) {
  const dir = new THREE.Vector3(dirSurf[0], dirSurf[2], dirSurf[1]).normalize(); // to world y-up
  const a = P0.clone().addScaledVector(dir, -2.6);
  const b = P0.clone().addScaledVector(dir, 2.6);
