const tanT1 = tangentSegment([1, 0, -0.264], 0x12796F);
const tanT2 = tangentSegment([0, 1, -0.04], 0xB9322B);

// extra swept curve + tangent (slider driven)
const EXTRA_COLOR = 0x6A4FB6;
let extraCurve = null, extraTan = null;
function rebuildExtra(thetaDeg) {
  const th = THREE.MathUtils.degToRad(thetaDeg);
  const cx = Math.cos(th), cy = Math.sin(th);
  const pts = [];
  for (let s = -6; s <= 6.0001; s += 0.08) {
    const x = X0 + s * cx, y = Y0 + s * cy;
    if (x < -3.5 || x > 3.5 || y < -3 || y > 3) continue;
    pts.push(W(x, y, hf(x, y) + 0.025));
  }
  const slope = -0.44 * X0 * cx - 0.20 * Y0 * cy;
  const dir = new THREE.Vector3(cx, slope, cy).normalize();
  const a = P0.clone().addScaledVector(dir, -2.6);
  const b = P0.clone().addScaledVector(dir, 2.6);

  if (extraCurve) { scene.remove(extraCurve); extraCurve.geometry.dispose(); extraCurve.material.dispose(); }
  if (extraTan) { scene.remove(extraTan); extraTan.geometry.dispose(); extraTan.material.dispose(); }
  extraCurve = makeTube(pts.length > 2 ? pts : [P0.clone(), P0.clone().add(dir)], EXTRA_COLOR, 0.030);
  extraTan = makeTube([a, P0.clone(), b], EXTRA_COLOR, 0.026);
  applyVis();
}

// P0 dot
const dot = new THREE.Mesh(
  new THREE.SphereGeometry(0.07, 24, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000 })
);
dot.position.copy(P0);
dot.renderOrder = 6;
scene.add(dot);

/* ── leader lines ────────────────────────────────────────────────────────── */
const leaderMat = new THREE.LineBasicMaterial({ color: 0x6B6B6B });
function leader(a, b) {
