}
leader(new THREE.Vector3(0.28, 3.22, -0.62), P0.clone().add(new THREE.Vector3(0.02, 0.12, 0)));
leader(new THREE.Vector3(-1.85, 0.62, 2.35), W(X0, 2.6, hf(X0, 2.6) + 0.06));

rebuildExtra(60);

/* ── camera ──────────────────────────────────────────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 40,
  elevationDeg: 22,
  rollDeg: 0,
  heightFraction: 0.68
});
controls.minPolarAngle = THREE.MathUtils.degToRad(10);
controls.maxPolarAngle = THREE.MathUtils.degToRad(85);
document.getElementById('btnReset').style.display = '';

/* ── labels ──────────────────────────────────────────────────────────────── */
const P0TXT = '<i>P</i><sub>0</sub>(<i>x</i><sub>0</sub>, <i>y</i><sub>0</sub>, <i>z</i><sub>0</sub>)';
addLabel('Tangent plane at<br>' + P0TXT,
