addLabel('Curve <i>C</i><br>passes through<br>' + P0TXT,
  new THREE.Vector3(-3.1, 0.55, 2.55), { color: '#231F20', fontSize: '13px' });
addLabel('<i>S</i>', new THREE.Vector3(3.0, 0.22, -2.25),
  { color: '#231F20', fontSize: '16px' });
const extraLbl = addLabel('extra curve<br>through ' + P0TXT,
  new THREE.Vector3(0, 0, 0), { color: '#6A4FB6', fontSize: '11px' });

/* ── state + fading ──────────────────────────────────────────────────────── */
const fade = {
  plane: { cur: 1, tgt: 1 },
  tang: { cur: 1, tgt: 1 },
  extra: { cur: 1, tgt: 1 }
};
let sel = 'both';

function selAmt(which) {
